create table alocacao (created_at timestamp(6), id_alocacao bigint generated by default as identity, id_bloco_horario bigint not null, id_dia_semana bigint not null, id_disciplina bigint not null, id_professor bigint not null, id_quadro_horario bigint not null, id_sala bigint not null, id_turma bigint not null, updated_at timestamp(6), primary key (id_alocacao)); 
create table bloco_horario (duracao integer not null, hora_fim time(0) not null, hora_inicio time(0) not null, created_at timestamp(6), id_bloco_horario bigint generated by default as identity, updated_at timestamp(6), primary key (id_bloco_horario)); 
create table curso (duracao integer not null, created_at timestamp(6), id_curso bigint generated by default as identity, updated_at timestamp(6), nome varchar(255) not null unique, periodicidade varchar(255) not null, status enum ('ATIVO','INATIVO') not null, primary key (id_curso)); 
create table dia_semana (id_dia_semana bigint generated by default as identity, nome varchar(20) not null unique, primary key (id_dia_semana)); 
create table disciplina (carga_horaria integer, periodo integer, created_at timestamp(6), id_curso bigint not null, id_disciplina bigint generated by default as identity, id_tipo_sala bigint not null, updated_at timestamp(6), cod_disciplina varchar(255) unique, cor varchar(255), modalidade varchar(255), nome varchar(255) not null, tipo_disciplina varchar(255) not null, primary key (id_disciplina)); 
create table disponibilidade_professor (created_at timestamp(6), id_bloco_horario bigint not null, id_dia_semana bigint not null, id_disponibilidade_professor bigint generated by default as identity, id_professor bigint not null, updated_at timestamp(6), primary key (id_disponibilidade_professor)); 
create table historico_versao_alocacao (data_alteracao date not null, id_alocacao bigint not null, id_historico_versao_alocacaoo bigint generated by default as identity, id_usuario bigint not null, campo_alterado varchar(255) not null, justificativa varchar(255) not null, valor_antigo varchar(255), valor_novo varchar(255) not null, primary key (id_historico_versao_alocacaoo)); 
create table periodo_atividade_quadro (ano integer, data_fim date, data_inicio date, periodo integer, created_at timestamp(6), id_periodo_atividade_quadro bigint generated by default as identity, updated_at timestamp(6), status enum ('ATIVO','INATIVO') not null, primary key (id_periodo_atividade_quadro)); 
create table professor (created_at timestamp(6), id_pessoa bigint generated by default as identity, updated_at timestamp(6), cidade varchar(255), email varchar(255) not null unique, nome varchar(255) not null, status enum ('ATIVO','INATIVO') not null, primary key (id_pessoa)); 
create table professor_disciplina (id_disciplina bigint not null, id_professor bigint not null, id_professor_disciplina bigint generated by default as identity, primary key (id_professor_disciplina)); 
create table quadro_horario (versao integer not null, created_at timestamp(6), data_criacao timestamp(6) not null, id_curso bigint not null, id_periodo_atividade_quadro bigint not null, id_quadro_horario bigint generated by default as identity, updated_at timestamp(6), status enum ('ATIVO','INATIVO') not null, primary key (id_quadro_horario)); 
create table recurso (created_at timestamp(6), id_recurso bigint generated by default as identity, id_tipo_recurso bigint not null, updated_at timestamp(6), nome varchar(255) not null unique, primary key (id_recurso)); 
create table recurso_sala (quantidade integer not null, created_at timestamp(6), id_recurso bigint not null, id_recurso_sala bigint generated by default as identity, id_sala bigint not null, updated_at timestamp(6), primary key (id_recurso_sala)); 
create table sala (capacidade integer not null, created_at timestamp(6), id_sala bigint generated by default as identity, id_tipo_sala bigint not null, updated_at timestamp(6), codigo varchar(255) not null, primary key (id_sala)); 
create table tipo_recurso (created_at timestamp(6), id_recurso bigint generated by default as identity, updated_at timestamp(6), nome varchar(255) not null unique, primary key (id_recurso)); 
create table tipo_sala (created_at timestamp(6), id_tipo_sala bigint generated by default as identity, updated_at timestamp(6), nome varchar(255) not null unique, primary key (id_tipo_sala)); 
create table turma (ano integer not null, numero_alunos integer not null, periodo integer not null, created_at timestamp(6), id_curso bigint not null, id_turma bigint generated by default as identity, updated_at timestamp(6), codigo varchar(255) not null, primary key (id_turma)); 
create table usuario (created_at timestamp(6), id_curso bigint, id_usuario bigint generated by default as identity, updated_at timestamp(6), email varchar(255) not null unique, nome varchar(255) not null, senha varchar(255) not null, status enum ('ATIVO','INATIVO') not null, tipo_usuario enum ('ADMINISTRADOR','COORDENADOR'), primary key (id_usuario)); 
